//! Scene spectrum and the observer that turns a dye transmittance back into RGB.
//!
//! ACEScg is upsampled with the sigmoid-polynomial model of Jakob and Hanika,
//! "A Low-Dimensional Function Space for Efficient Spectral Upsampling",
//! Computer Graphics Forum 38(2), 2019. Coefficients for ACES2065-1 come from
//! a table generated by mitsuba-renderer/rgb2spec (BSD-3-Clause). See
//! `data/NOTICE`. Every color is looked up at the same AP0 peak of 1/2 and
//! the spectrum is multiplied back up, so exposure scales the spectrum
//! without changing its shape. A neutral ACEScg gray is the
//! closed form: a flat spectrum at the gray's level, so that round trip does
//! not depend on the table.
//!
//! The dye scan integrates transmittance against the CIE 1931 2 degree
//! observer under D65, then the existing D65 → ACEScg matrix. The result is
//! scaled so a clear film (transmittance 1) is ACEScg `(1, 1, 1)`.

use std::sync::OnceLock;

#[cfg(test)]
use crate::cie1931::CIE_D60;
use crate::cie1931::{CIE_D65, CIE_LAMBDA_MAX, CIE_LAMBDA_MIN, CIE_X, CIE_Y, CIE_Z};
use crate::matrices;

const COEFFS: usize = 3;

/// Resolved sigmoid coefficients and the intensity carried outside the model.
struct Upsample {
    coeff: [f32; COEFFS],
    scale: f32,
}

/// Precomputed dye-scan weights on one wavelength grid.
///
/// `rows[channel][index]` already includes the trapezoidal weight and the
/// white normalisation. Dot a transmittance with one row to get that ACEScg
/// channel.
#[derive(Debug, Clone)]
pub(crate) struct Observer {
    rows: [Vec<f32>; 3],
}

impl Observer {
    /// D65, CIE 1931, expressed in ACEScg, on `wavelengths`.
    ///
    /// `None` when the grid does not meet the visible observer, which would
    /// make the white normalisation divide by zero.
    pub(crate) fn acescg_d65(wavelengths: &[f32]) -> Option<Self> {
        let matrix = matrices::xyz_d65_to_acescg();
        project_rows(wavelengths, &CIE_D65, matrix)
    }

    /// Weights per channel, the trapezoid and white already folded in.
    #[cfg(feature = "gpu")]
    pub(crate) fn rows(&self) -> &[Vec<f32>; 3] {
        &self.rows
    }

    /// ACEScg channels of a transmittance sampled on this observer's grid.
    pub(crate) fn apply(&self, transmittance: &[f32]) -> [f32; 3] {
        let mut rgb = [0.0f32; 3];
        for (channel, row) in self.rows.iter().enumerate() {
            let mut sum = 0.0f32;
            for (weight, sample) in row.iter().zip(transmittance) {
                sum += weight * sample;
            }
            rgb[channel] = sum;
        }
        rgb
    }
}

/// Write the Jakob-Hanika spectrum of an ACEScg pixel into `out`.
///
/// `out` and `wavelengths` are the same length. Channels that are negative or
/// non-finite are treated as zero before the upsampling: a reflectance model
/// has no negative samples, and the characteristic curve already floors
/// exposure.
pub(crate) fn fill_scene_spectrum(rgb: [f32; 3], wavelengths: &[f32], out: &mut [f32]) {
    debug_assert_eq!(wavelengths.len(), out.len());
    let upsample = upsample(rgb);
    if upsample.coeff == [0.0, 0.0, 0.0] && upsample.scale == 0.0 {
        out.fill(0.0);
        return;
    }
    if upsample.coeff[0] == 0.0 && upsample.coeff[1] == 0.0 {
        // Flat spectrum: the closed form does not depend on wavelength.
        let level = eval(upsample.coeff, 0.0) * upsample.scale;
        out.fill(level);
        return;
    }
    // Table coefficients are the quadratic in nanometres. rgb2spec remaps
    // the normalised fit back to 360–830 nm before writing the file.
    for (sample, wavelength) in out.iter_mut().zip(wavelengths) {
        *sample = eval(upsample.coeff, *wavelength) * upsample.scale;
    }
}

/// Integrate `spectrum` against CIE 1931 and D60 and return ACES2065-1.
///
/// The coefficient table was fit with rgb2spec's Simpson's 3/8 rule on
/// `(95 - 1) * 3 + 1` wavelengths from 360 nm to 830 nm, with the XYZ→AP0
/// matrix inside the sum. This resamples `spectrum` onto that grid and uses
/// the same weights, divided by the white so a flat spectrum of 1 is AP0
/// `(1, 1, 1)`. Saturated primaries still miss: no spectrum in `(0, 1)`
/// integrates to AP0 `(1, 0, 0)`. Used to check the upsampler.
#[cfg(test)]
pub(crate) fn spectrum_to_ap0(spectrum: &[f32], wavelengths: &[f32]) -> [f32; 3] {
    let rows = ap0_fine_rows();
    let mut rgb = [0.0f32; 3];
    for (index, row) in rows.iter().enumerate() {
        let sample = interp_spectrum(spectrum, wavelengths, fine_wavelength(index));
        for channel in 0..3 {
            rgb[channel] += row[channel] * sample;
        }
    }
    rgb
}

/// rgb2spec `CIE_FINE_SAMPLES`: three interior nodes per 5 nm CIE interval.
#[cfg(test)]
const FINE_SAMPLES: usize = (95 - 1) * 3 + 1;

#[cfg(test)]
fn fine_wavelength(index: usize) -> f32 {
    let h = (CIE_LAMBDA_MAX - CIE_LAMBDA_MIN) / (FINE_SAMPLES - 1) as f32;
    CIE_LAMBDA_MIN + index as f32 * h
}

#[cfg(test)]
fn ap0_fine_rows() -> &'static [[f32; 3]; FINE_SAMPLES] {
    static ROWS: OnceLock<[[f32; 3]; FINE_SAMPLES]> = OnceLock::new();
    ROWS.get_or_init(|| {
        let matrix = matrices::xyz_d60_to_ap0();
        let h = f64::from(CIE_LAMBDA_MAX - CIE_LAMBDA_MIN) / (FINE_SAMPLES - 1) as f64;
        let mut sums = [[0.0f64; 3]; FINE_SAMPLES];
        let mut white = [0.0f64; 3];
        for (index, slot) in sums.iter_mut().enumerate() {
            // rgb2spec_opt.cpp init_tables: 3/8 * h, doubled on every third
            // interior node, tripled on the others, endpoints left as 3/8 * h.
            let mut weight = 3.0 / 8.0 * h;
            if index != 0 && index + 1 != FINE_SAMPLES {
                if (index - 1) % 3 == 2 {
                    weight *= 2.0;
                } else {
                    weight *= 3.0;
                }
            }
            let lambda = f64::from(fine_wavelength(index));
            let cmf = cie_xyz(lambda as f32);
            let light = f64::from(cie_at(&CIE_D60, lambda as f32));
            let xyz = [
                cmf[0] * light * weight,
                cmf[1] * light * weight,
                cmf[2] * light * weight,
            ];
            let rgb = matrices::apply(matrix, xyz);
            *slot = rgb;
            for channel in 0..3 {
                white[channel] += rgb[channel];
            }
        }
        let mut rows = [[0.0f32; 3]; FINE_SAMPLES];
        for (row, sum) in rows.iter_mut().zip(sums) {
            // The raw sum of a flat spectrum is the D60 white through AP0,
            // within about a thousandth of (1, 1, 1). Divide it out so a
            // neutral gray integrates back to itself.
            *row = [
                (sum[0] / white[0]) as f32,
                (sum[1] / white[1]) as f32,
                (sum[2] / white[2]) as f32,
            ];
        }
        rows
    })
}

#[cfg(test)]
fn interp_spectrum(spectrum: &[f32], wavelengths: &[f32], lambda: f32) -> f32 {
    if spectrum.is_empty() || wavelengths.is_empty() {
        return 0.0;
    }
    if lambda <= wavelengths[0] {
        return spectrum[0];
    }
    let last = wavelengths.len() - 1;
    if lambda >= wavelengths[last] {
        return spectrum[last.min(spectrum.len() - 1)];
    }
    let upper = wavelengths.partition_point(|&sample| sample < lambda);
    let lower = upper - 1;
    let span = wavelengths[upper] - wavelengths[lower];
    if span == 0.0 {
        return spectrum[lower];
    }
    let weight = (lambda - wavelengths[lower]) / span;
    spectrum[lower] * (1.0 - weight) + spectrum[upper] * weight
}

fn upsample(rgb: [f32; 3]) -> Upsample {
    let rgb = rgb.map(|channel| {
        if channel.is_finite() {
            channel.max(0.0)
        } else {
            0.0
        }
    });
    let max = rgb[0].max(rgb[1]).max(rgb[2]);
    if max == 0.0 {
        return Upsample {
            coeff: [0.0; COEFFS],
            scale: 0.0,
        };
    }
    let min = rgb[0].min(rgb[1]).min(rgb[2]);
    // A neutral is a flat spectrum at its own level. The tolerance is only
    // wide enough to absorb an ulp of matrix noise, not a real chroma.
    if max - min <= 1.0e-4 * max.max(1.0) {
        let level = (rgb[0] + rgb[1] + rgb[2]) / 3.0;
        return Upsample {
            coeff: mono_coeff(1.0),
            scale: level,
        };
    }
    let ap0 = apply3(ap1_to_ap0(), rgb).map(|channel| channel.max(0.0));
    let peak = ap0[0].max(ap0[1]).max(ap0[2]);
    if peak == 0.0 {
        return Upsample {
            coeff: [0.0; COEFFS],
            scale: 0.0,
        };
    }
    // Scene light is unbounded, so the spectrum's shape must not depend on
    // brightness: look up the chromaticity at a fixed peak and carry the
    // intensity in `scale`, as pbrt-v4's RGBUnboundedSpectrum does. The
    // fixed peak is 1/2 rather than 1 because the sigmoid is a reflectance
    // in (0, 1): near 1 it cannot reach saturated colors, and the table's
    // fits change shape quickly there. Looking up `ap0` itself below 1 made
    // a bright saturated color stop brightening and shift hue before the
    // peak reached 1, then jump spectra at 1 (#42).
    let scale = 2.0 * peak;
    Upsample {
        coeff: table().fetch(ap0.map(|channel| channel / scale)),
        scale,
    }
}

/// `0.5 + 0.5 * c / sqrt(1 + c^2)`. `lambda` is in the same units as `coeff`.
fn eval(coeff: [f32; COEFFS], lambda: f32) -> f32 {
    let polynomial = (coeff[0] * lambda + coeff[1]) * lambda + coeff[2];
    0.5 * polynomial / (polynomial * polynomial + 1.0).sqrt() + 0.5
}

/// The upsampling table and the AP1 → AP0 matrix, for the GPU.
///
/// Returns the cube resolution, the z scale, and the coefficients, in the
/// layout [`Rgb2Spec::fetch`] reads.
#[cfg(feature = "gpu")]
pub(crate) fn gpu_upsample() -> (u32, &'static [f32], &'static [f32], [[f32; 3]; 3]) {
    let table = table();
    (table.res as u32, &table.scale, &table.data, ap1_to_ap0())
}

fn ap1_to_ap0() -> [[f32; 3]; 3] {
    static MATRIX: OnceLock<[[f32; 3]; 3]> = OnceLock::new();
    *MATRIX.get_or_init(|| matrices::ap1_to_ap0().map(|row| row.map(|value| value as f32)))
}

fn apply3(matrix: [[f32; 3]; 3], value: [f32; 3]) -> [f32; 3] {
    [
        matrix[0][0] * value[0] + matrix[0][1] * value[1] + matrix[0][2] * value[2],
        matrix[1][0] * value[0] + matrix[1][1] * value[1] + matrix[1][2] * value[2],
        matrix[2][0] * value[0] + matrix[2][1] * value[1] + matrix[2][2] * value[2],
    ]
}

fn mono_coeff(value: f32) -> [f32; COEFFS] {
    // rgb2spec's closed form. ±8192 evaluates to 0 or 1 in f32; a real
    // infinity would poison the quadratic.
    let constant = if value <= 0.0 {
        -8192.0
    } else if value >= 1.0 {
        8192.0
    } else {
        (value - 0.5) / (value * (1.0 - value)).sqrt()
    };
    [0.0, 0.0, constant]
}

fn project_rows(
    wavelengths: &[f32],
    illuminant: &[f32; 95],
    matrix: [[f64; 3]; 3],
) -> Option<Observer> {
    let mut weighted = vec![[0.0f64; 3]; wavelengths.len()];
    let mut white = [0.0f64; 3];
    for index in 0..wavelengths.len() {
        let left = if index == 0 {
            0.0
        } else {
            wavelengths[index] - wavelengths[index - 1]
        };
        let right = if index + 1 == wavelengths.len() {
            0.0
        } else {
            wavelengths[index + 1] - wavelengths[index]
        };
        let weight = 0.5 * f64::from(left + right);
        let cmf = cie_xyz(wavelengths[index]);
        let light = f64::from(cie_at(illuminant, wavelengths[index]));
        let sample = [
            cmf[0] * light * weight,
            cmf[1] * light * weight,
            cmf[2] * light * weight,
        ];
        for channel in 0..3 {
            white[channel] += sample[channel];
        }
        weighted[index] = sample;
    }
    let white_rgb = matrices::apply(matrix, white);
    if white_rgb
        .iter()
        .any(|channel| !channel.is_finite() || channel.abs() < 1.0e-8)
    {
        return None;
    }
    let mut rows = [Vec::new(), Vec::new(), Vec::new()];
    for channel in 0..3 {
        rows[channel] = weighted
            .iter()
            .map(|sample| (matrices::apply(matrix, *sample)[channel] / white_rgb[channel]) as f32)
            .collect();
    }
    Some(Observer { rows })
}

fn cie_xyz(wavelength: f32) -> [f64; 3] {
    [
        f64::from(cie_at(&CIE_X, wavelength)),
        f64::from(cie_at(&CIE_Y, wavelength)),
        f64::from(cie_at(&CIE_Z, wavelength)),
    ]
}

fn cie_at(table: &[f32; 95], wavelength: f32) -> f32 {
    let scaled = (wavelength - CIE_LAMBDA_MIN) / (CIE_LAMBDA_MAX - CIE_LAMBDA_MIN) * 94.0;
    let scaled = scaled.clamp(0.0, 94.0);
    let index = (scaled.floor() as usize).min(93);
    let weight = scaled - index as f32;
    table[index] * (1.0 - weight) + table[index + 1] * weight
}

struct Rgb2Spec {
    res: usize,
    scale: Vec<f32>,
    data: Vec<f32>,
}

fn table() -> &'static Rgb2Spec {
    static TABLE: OnceLock<Rgb2Spec> = OnceLock::new();
    TABLE.get_or_init(|| {
        Rgb2Spec::parse(include_bytes!("../data/aces2065-1.coeff"))
            .expect("ACES2065-1 Jakob-Hanika coefficient table")
    })
}

impl Rgb2Spec {
    fn parse(bytes: &[u8]) -> Result<Self, &'static str> {
        if bytes.len() < 8 || &bytes[..4] != b"SPEC" {
            return Err("rgb2spec table is missing the SPEC header");
        }
        let res = u32::from_le_bytes(bytes[4..8].try_into().unwrap()) as usize;
        if res < 2 {
            return Err("rgb2spec resolution is too small");
        }
        let scale_bytes = res.checked_mul(4).ok_or("rgb2spec scale overflows")?;
        let cube = res
            .checked_mul(res)
            .and_then(|area| area.checked_mul(res))
            .ok_or("rgb2spec resolution overflows")?;
        let data_bytes = cube
            .checked_mul(9)
            .and_then(|count| count.checked_mul(4))
            .ok_or("rgb2spec coefficients overflow")?;
        let needed = 8usize
            .checked_add(scale_bytes)
            .and_then(|offset| offset.checked_add(data_bytes))
            .ok_or("rgb2spec table size overflows")?;
        if bytes.len() < needed {
            return Err("rgb2spec table is truncated");
        }
        Ok(Self {
            res,
            scale: read_f32s(&bytes[8..8 + scale_bytes]),
            data: read_f32s(&bytes[8 + scale_bytes..needed]),
        })
    }

    /// Trilinear fetch from rgb2spec. `rgb` is clamped to `[0, 1]`.
    fn fetch(&self, rgb: [f32; 3]) -> [f32; COEFFS] {
        let rgb = rgb.map(|channel| channel.clamp(0.0, 1.0));
        if rgb[0] == rgb[1] && rgb[1] == rgb[2] {
            return mono_coeff(rgb[0]);
        }
        let mut max_channel = 0usize;
        for channel in 1..3 {
            if rgb[channel] >= rgb[max_channel] {
                max_channel = channel;
            }
        }
        let z = rgb[max_channel];
        if z <= 0.0 {
            return [self.data[0], self.data[1], self.data[2]];
        }
        let scale = (self.res - 1) as f32 / z;
        let x = rgb[(max_channel + 1) % 3] * scale;
        let y = rgb[(max_channel + 2) % 3] * scale;
        let xi = (x as usize).min(self.res - 2);
        let yi = (y as usize).min(self.res - 2);
        let zi = find_interval(&self.scale, z);
        let base = (((max_channel * self.res + zi) * self.res + yi) * self.res + xi) * COEFFS;
        let dx = COEFFS;
        let dy = COEFFS * self.res;
        let dz = COEFFS * self.res * self.res;
        let x1 = x - xi as f32;
        let y1 = y - yi as f32;
        let x0 = 1.0 - x1;
        let y0 = 1.0 - y1;
        let z1 = (z - self.scale[zi]) / (self.scale[zi + 1] - self.scale[zi]);
        let z0 = 1.0 - z1;
        let mut coeff = [0.0f32; COEFFS];
        for (term_index, term) in coeff.iter_mut().enumerate() {
            let at = |shift: usize| self.data[base + term_index + shift];
            *term = ((at(0) * x0 + at(dx) * x1) * y0 + (at(dy) * x0 + at(dy + dx) * x1) * y1) * z0
                + ((at(dz) * x0 + at(dz + dx) * x1) * y0
                    + (at(dz + dy) * x0 + at(dz + dy + dx) * x1) * y1)
                    * z1;
        }
        coeff
    }
}

fn find_interval(scale: &[f32], value: f32) -> usize {
    let mut left = 0usize;
    let last = scale.len() - 2;
    let mut size = last;
    while size > 0 {
        let half = size >> 1;
        let middle = left + half + 1;
        if scale[middle] <= value {
            left = middle;
            size -= half + 1;
        } else {
            size = half;
        }
    }
    left.min(last)
}

fn read_f32s(bytes: &[u8]) -> Vec<f32> {
    let (chunks, _) = bytes.as_chunks::<4>();
    chunks.iter().copied().map(f32::from_le_bytes).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn visible_grid() -> Vec<f32> {
        (0..95).map(|index| 360.0 + index as f32 * 5.0).collect()
    }

    #[test]
    fn neutral_gray_is_a_flat_spectrum() {
        let grid = visible_grid();
        let mut spectrum = vec![0.0; grid.len()];
        for level in [0.02_f32, 0.18, 0.5, 1.0, 2.5] {
            fill_scene_spectrum([level, level, level], &grid, &mut spectrum);
            for sample in &spectrum {
                assert!(
                    (sample - level).abs() < 1.0e-5,
                    "gray {level} produced {sample}"
                );
            }
            let recovered = spectrum_to_ap0(&spectrum, &grid);
            let spread = recovered.into_iter().fold(0.0f32, f32::max)
                - recovered.into_iter().fold(f32::MAX, f32::min);
            assert!(spread < 1.0e-4, "recovered gray drifted: {recovered:?}");
            for channel in recovered {
                assert!((channel - level).abs() < 1.0e-3, "{recovered:?} != {level}");
            }
        }
    }

    fn fine_grid() -> Vec<f32> {
        (0..FINE_SAMPLES).map(fine_wavelength).collect()
    }

    #[test]
    fn chromatic_acescg_round_trips_near_the_input() {
        // Colors whose ACES2065-1 image is inside the sigmoid model. A unit
        // primary is not: the fit is a reflectance in (0, 1), and no such
        // spectrum integrates to AP0 (1, 0, 0).
        let grid = fine_grid();
        let mut spectrum = vec![0.0; grid.len()];
        let colors = [
            [0.35, 0.25, 0.18],
            [0.2, 0.45, 0.15],
            [0.55, 0.48, 0.40],
            [0.15, 0.22, 0.28],
            [0.7, 0.55, 0.35],
        ];
        for color in colors {
            fill_scene_spectrum(color, &grid, &mut spectrum);
            let ap0 = spectrum_to_ap0(&spectrum, &grid);
            let recovered = matrices::apply(matrices::ap0_to_ap1(), ap0.map(f64::from));
            for (got, want) in recovered.into_iter().zip(color) {
                assert!(
                    (got as f32 - want).abs() < 0.02,
                    "{color:?} recovered {recovered:?}"
                );
            }
        }
    }

    #[test]
    fn hdr_near_white_round_trips() {
        let grid = fine_grid();
        let mut spectrum = vec![0.0; grid.len()];
        let color = [2.0, 1.85, 1.7];
        fill_scene_spectrum(color, &grid, &mut spectrum);
        let ap0 = spectrum_to_ap0(&spectrum, &grid);
        let recovered = matrices::apply(matrices::ap0_to_ap1(), ap0.map(f64::from));
        for (got, want) in recovered.into_iter().zip(color) {
            assert!(
                (got as f32 - want).abs() < 0.04,
                "{color:?} recovered {recovered:?}"
            );
        }
    }

    #[test]
    fn saturated_primary_stays_in_hue_but_loses_energy() {
        let grid = fine_grid();
        let mut spectrum = vec![0.0; grid.len()];
        fill_scene_spectrum([1.0, 0.0, 0.0], &grid, &mut spectrum);
        let ap0 = spectrum_to_ap0(&spectrum, &grid);
        assert!(ap0[0] > ap0[1] && ap0[1] > ap0[2], "{ap0:?}");
        assert!(
            ap0[0] < 0.7,
            "a unit reflectance cannot reach AP0 red 1: {ap0:?}"
        );
        assert!(ap0[0] > 0.3, "{ap0:?}");
    }

    #[test]
    fn exposure_scales_a_saturated_spectrum_without_a_step() {
        // #42: bright saturated colors used to plateau and change spectral
        // shape on the way to AP0 peak 1. A brightness ramp through 1 must
        // scale one spectrum, and that spectrum must still integrate back
        // to the color.
        let grid = fine_grid();
        let mut base = vec![0.0; grid.len()];
        let mut spectrum = vec![0.0; grid.len()];
        let colors = [
            [0.9, 0.15, 0.05],
            [0.2, 0.8, 0.1],
            [0.1, 0.2, 0.9],
            [0.9, 0.6, 0.05],
        ];
        for color in colors {
            let peak = apply3(ap1_to_ap0(), color)
                .into_iter()
                .fold(0.0f32, f32::max);
            let unit = color.map(|channel| channel / peak);
            fill_scene_spectrum(unit, &grid, &mut base);
            for step in 0..=40 {
                let exposure = 0.1 * 1.1f32.powi(step);
                let scaled = unit.map(|channel| channel * exposure);
                fill_scene_spectrum(scaled, &grid, &mut spectrum);
                for (got, want) in spectrum.iter().zip(&base) {
                    assert!(
                        (got - want * exposure).abs() <= 1.0e-4 * exposure,
                        "{color:?} at peak {exposure} changed shape"
                    );
                }
                let ap0 = spectrum_to_ap0(&spectrum, &grid);
                let recovered = matrices::apply(matrices::ap0_to_ap1(), ap0.map(f64::from));
                for (got, want) in recovered.into_iter().zip(scaled) {
                    assert!(
                        (got as f32 - want).abs() < 0.03 * exposure,
                        "{color:?} at peak {exposure} recovered {recovered:?}"
                    );
                }
            }
        }
    }

    #[test]
    fn clear_film_is_neutral_acescg() {
        let grid: Vec<f32> = (0..41).map(|index| 380.0 + index as f32 * 10.0).collect();
        let observer = Observer::acescg_d65(&grid).unwrap();
        let white = observer.apply(&vec![1.0; grid.len()]);
        for channel in white {
            assert!((channel - 1.0).abs() < 1.0e-4, "{white:?}");
        }
        let density = 0.3f32;
        let transmittance = vec![10f32.powf(-density); grid.len()];
        let gray = observer.apply(&transmittance);
        for channel in gray {
            assert!((channel - 10f32.powf(-density)).abs() < 1.0e-4, "{gray:?}");
        }
    }
}
